import{cargoOfficerLayers,drawCargoOfficer}from'./officer-presentation.mjs';
import{drawRescueHarin,drawBridgeRescueForeground}from'./rescue-presentation.mjs';
import{loadEngineSideBarriers}from'./engine-side-barriers.mjs';
import{applyWater,phaseAt}from'./water/water.mjs';import{createNight}from'./night/night.mjs';import{sampleNightMix}from'./night/day-night.mjs';import{drawDoor}from'./original-door-render.mjs';import{createDoorState}from'./door-state.mjs';
export async function createEnvironment({contract:c,readJSON,readBytes,getArt,getChestClaimState=()=>false,getRescueAllyCompleted=()=>false}){const envelopes=await readJSON('VISUAL_ENVELOPES_R3.json'),waterManifest=await readJSON('water/MANIFEST.json'),nightManifest=await readJSON('night/MANIFEST.json'),images={},waterData={},nightApply={},states=Object.fromEntries(c.rooms.map(r=>[r.roomId,createDoorState()]));states[c.bossGate.gateId]=createDoorState();
let sideBarriers;
try { sideBarriers=await loadEngineSideBarriers({readBytes});for(const n of ['front-panel-130x52','front-frame-146x60','side-panel-24x120','side-frame-40x136','switch-on-18x24','switch-off-18x24','supply-chest-closed-combined','supply-chest-open-combined']){images[n]=await createImageBitmap(new Blob([await readBytes('assets/'+n+'.png')],{type:'image/png'}))};
for(const name of Object.keys(waterManifest.scenes))waterData[name]={indices:new Uint32Array((await readBytes('water/'+name+'.indices.u32')).buffer),rgb:await readBytes('water/'+name+'.water48.rgb')};
for(const[name,s]of Object.entries(nightManifest))nightApply[name]=createNight(s,new Uint32Array((await readBytes('night/'+name+'.u32')).buffer),new Float64Array((await readBytes('night/'+name+'.f64')).buffer));
} catch(e){sideBarriers?.dispose();for(const i of Object.values(images))i.close();throw e}

const world=document.createElement('canvas');world.width=1536;world.height=1024;const w=world.getContext('2d');let cache='';
function renderDoor(ctx,d,p){const v=envelopes.doors[d.roomId];if(v){const[x,y,W,H]=v.innerRectXYWH,e=p*p*(3-2*p);ctx.save();ctx.beginPath();ctx.rect(x,y,W,H);ctx.clip();ctx.drawImage(images['front-panel-130x52'],0,0,65,52,x-W/2*e,y,W/2,H);ctx.drawImage(images['front-panel-130x52'],65,0,65,52,x+W/2+W/2*e,y,W/2,H);ctx.restore()}else if(d.asset==='side'){const[cx,cy]=d.pivotWorld,H=d.clearWidth,y=cy-H/2,e=p*p*(3-2*p),f=images['side-frame-40x136'];ctx.save();ctx.beginPath();ctx.rect(cx-12,y,24,H);ctx.clip();ctx.drawImage(images['side-panel-24x120'],0,0,24,60,cx-12,y-H/2*e,24,H/2);ctx.drawImage(images['side-panel-24x120'],0,60,24,60,cx-12,cy+H/2*e,24,H/2);ctx.restore();ctx.drawImage(f,0,0,40,8,cx-20,y-8,40,8);ctx.drawImage(f,0,128,40,8,cx-20,y+H,40,8);ctx.drawImage(f,0,8,8,120,cx-20,y,8,H);ctx.drawImage(f,32,8,8,120,cx+12,y,8,H)}else drawDoor(ctx,{panel:images['front-panel-130x52'],frame:images['front-frame-146x60']},{cx:d.pivotWorld[0],cy:d.pivotWorld[1],width:d.clearWidth,progress:p});for(const[x,y]of d.switchVisualAnchors)ctx.drawImage(images[p===1?'switch-on-18x24':'switch-off-18x24'],x-9,y-12)}


return{dispose(){sideBarriers.dispose();for(const i of Object.values(images))i.close();world.width=world.height=0;},syncDoors(next){for(const id of Object.keys(states)){const d=next[id]??(id===c.bossGate.gateId?createDoorState():null);if(!d||!['open','closed','opening','closing'].includes(d.phase)||!Number.isFinite(d.progress)||d.progress<0||d.progress>1)throw Error('Door state mismatch');states[id]={...d};}},frame(scene,elapsed,minutes,enabled=true,actor=null){const chestStates=Object.fromEntries(c.chests.filter(a=>a.map===scene).map(a=>[a.id,getChestClaimState(a.id)===true])),phase=phaseAt(elapsed),mix=sampleNightMix(minutes,{dawnStart:300,dayStart:420,duskStart:1080,nightStart:1200}),key=JSON.stringify([scene,phase,minutes,enabled,chestStates,c.rooms.filter(r=>r.mapId===scene).map(r=>states[r.roomId].progress),states[c.bossGate.gateId].progress]);if(!actor&&key===cache)return{canvas:world,phase,mix:nightApply[scene]?mix:0};w.drawImage(getArt(scene),0,0);if(enabled&&waterData[scene]){const d=waterData[scene],f=w.getImageData(0,0,1536,1024);applyWater(f.data,d.indices,d.rgb,phase,{scene,camera:[0,0,1536,1024],revision:waterManifest.revision,enabled:true,conflict:false,sourceSHA:c.scenes.find(s=>s.map===scene).sha256},waterManifest);w.putImageData(f,0,0)}if(scene==='ship_engine')sideBarriers.drawBase(w);const layers=c.rooms.filter(r=>r.mapId===scene).map(r=>({kind:'door',door:r.door,progress:states[r.roomId].progress,depthY:r.door.pivotWorld[1]+8}));if(scene==='ship_bridge')layers.push({kind:'door',door:c.bossGate,progress:states[c.bossGate.gateId].progress,depthY:c.bossGate.pivotWorld[1]+8});for(const a of c.chests.filter(a=>a.map===scene))layers.push({kind:'chest',chest:a,depthY:a.position[1]+3});if(scene==='ship_engine')layers.push({kind:'sideBarrier',depthY:212});if(scene==='ship_rescue')layers.push({kind:'rescueHarin',depthY:400});layers.push(...cargoOfficerLayers(scene));layers.sort((a,b)=>a.depthY-b.depthY);let drawn=false;for(const layer of layers){if(actor&&!drawn&&actor.footY<=layer.depthY){actor.draw(w);drawn=true}if(layer.kind==='cargoOfficer')drawCargoOfficer(w,layer.row);else if(layer.kind==='rescueHarin')drawRescueHarin(w,{completed:getRescueAllyCompleted()});else if(layer.kind==='sideBarrier')sideBarriers.drawForeground(w);else if(layer.kind==='door')renderDoor(w,layer.door,layer.progress);else{const a=layer.chest;w.drawImage(images[chestStates[a.id]?'supply-chest-open-combined':'supply-chest-closed-combined'],a.position[0]-48,a.position[1]-74)}}if(actor&&!drawn)actor.draw(w);if(scene==='ship_bridge')drawBridgeRescueForeground(w,getArt(scene));if(nightApply[scene]){const f=w.getImageData(0,0,1536,1024);nightApply[scene](f.data,[0,0],1536,1024,mix);w.putImageData(f,0,0)}cache=key;return{canvas:world,phase,mix:nightApply[scene]?mix:0}}};}
